-- TỰ SINH bởi scripts/seed/generate.mjs — không sửa tay. Chạy sau supabase/schema.sql.
-- Upsert theo id: chạy lại được, không xoá dữ liệu admin đã thêm.
begin;

-- Dự án
on conflict (id) do update set
  name = excluded.name,
  type = excluded.type,
  location = excluded.location,
  status = excluded.status,
  price = excluded.price,
  interest_count = excluded.interest_count,
  popularity = excluded.popularity,
  building_type = excluded.building_type,
  description = excluded.description,
  overview = excluded.overview,
  sort_order = excluded.sort_order,
  created_at = excluded.created_at;
select setval(pg_get_serial_sequence('public.projects', 'id'), (select max(id) from public.projects));

-- Tin tức (ảnh để trống → web dùng ảnh mẫu cùng id)
on conflict (id) do update set
  category = excluded.category,
  title = excluded.title,
  content = excluded.content,
  published_at = excluded.published_at,
  is_featured = excluded.is_featured,
  is_published = excluded.is_published;
select setval(pg_get_serial_sequence('public.news', 'id'), (select max(id) from public.news));

-- Tuyển dụng
on conflict (id) do update set
  title = excluded.title,
  location = excluded.location,
  employment_type = excluded.employment_type,
  summary = excluded.summary,
  icon = excluded.icon,
  is_open = excluded.is_open,
  sort_order = excluded.sort_order;
select setval(pg_get_serial_sequence('public.jobs', 'id'), (select max(id) from public.jobs));

-- Mặt bằng mặc định theo loại hình (thay toàn bộ mặt bằng con của bộ mặc định)
values ('apartment', 'Mặt bằng căn hộ', 'Các loại căn hộ được thiết kế tối ưu công năng, không gian sinh hoạt chung liền mạch, mọi phòng ngủ đều đón ánh sáng và gió tự nhiên.')
on conflict (building_type) where project_id is null do update set title = excluded.title, intro = excluded.intro;
delete from public.floor_plans where set_id = (select id from public.floor_plan_sets where building_type = 'apartment' and project_id is null);
select (select id from public.floor_plan_sets where building_type = 'apartment' and project_id is null), v.slug, v.name, v.code, v.area::numeric, v.bedrooms::int, v.bathrooms::int, v.note,
  v.width::numeric, v.depth::numeric, v.rooms::jsonb, v.sort_order::int
from (values
  ('a1', '1 phòng ngủ', 'A1', 52, 1, 1, 'Căn hộ nhỏ gọn cho người trẻ độc thân hoặc vợ chồng mới cưới, phù hợp cho thuê.', 8, 6.5, '[{"label":"Bếp","kind":"kitchen","x":0,"y":0,"w":3,"h":2.5},{"label":"WC","kind":"wc","x":3,"y":0,"w":2,"h":2.5},{"label":"Phòng ngủ","kind":"bed","x":5,"y":0,"w":3,"h":4.5},{"label":"Phòng khách","kind":"living","x":0,"y":2.5,"w":5,"h":4},{"label":"Ban công","kind":"outdoor","x":5,"y":4.5,"w":3,"h":2}]'::jsonb, 0),
  ('b2', '2 phòng ngủ', 'B2', 75, 2, 2, 'Lựa chọn phổ biến nhất cho gia đình trẻ, phòng ngủ master có WC riêng.', 10, 7.5, '[{"label":"Bếp","kind":"kitchen","x":0,"y":0,"w":3,"h":3.5},{"label":"WC","kind":"wc","x":3,"y":0,"w":2,"h":3.5},{"label":"Phòng ngủ master","kind":"bed","x":5,"y":0,"w":5,"h":3.5},{"label":"Phòng khách","kind":"living","x":0,"y":3.5,"w":6,"h":4},{"label":"Phòng ngủ 2","kind":"bed","x":6,"y":3.5,"w":4,"h":3},{"label":"Ban công","kind":"outdoor","x":6,"y":6.5,"w":4,"h":1}]'::jsonb, 1),
  ('c3', '3 phòng ngủ', 'C3', 96, 3, 2, 'Căn góc 2 mặt thoáng cho gia đình nhiều thế hệ, lô gia rộng để giặt phơi.', 12, 8, '[{"label":"Phòng ngủ 2","kind":"bed","x":0,"y":0,"w":3.5,"h":3.5},{"label":"WC","kind":"wc","x":3.5,"y":0,"w":2,"h":3.5},{"label":"Bếp","kind":"kitchen","x":5.5,"y":0,"w":3,"h":3.5},{"label":"Phòng ngủ 3","kind":"bed","x":8.5,"y":0,"w":3.5,"h":3.5},{"label":"Phòng khách","kind":"living","x":0,"y":3.5,"w":6.5,"h":4.5},{"label":"Phòng ngủ master","kind":"bed","x":6.5,"y":3.5,"w":4,"h":4.5},{"label":"WC","kind":"wc","x":10.5,"y":3.5,"w":1.5,"h":2.5},{"label":"Lô gia","kind":"outdoor","x":10.5,"y":6,"w":1.5,"h":2}]'::jsonb, 2)
) as v (slug, name, code, area, bedrooms, bathrooms, note, width, depth, rooms, sort_order);

values ('villa', 'Mặt bằng biệt thự', 'Biệt thự song lập trên lô đất 12 × 15m, tầng 1 dành cho sinh hoạt chung và tiếp khách, tầng 2 là không gian nghỉ ngơi riêng tư của gia đình.')
on conflict (building_type) where project_id is null do update set title = excluded.title, intro = excluded.intro;
delete from public.floor_plans where set_id = (select id from public.floor_plan_sets where building_type = 'villa' and project_id is null);
select (select id from public.floor_plan_sets where building_type = 'villa' and project_id is null), v.slug, v.name, v.code, v.area::numeric, v.bedrooms::int, v.bathrooms::int, v.note,
  v.width::numeric, v.depth::numeric, v.rooms::jsonb, v.sort_order::int
from (values
  ('t1', 'Tầng 1', 'T1', 180, 1, 1, 'Gara ô tô, phòng khách thông tầng, bếp mở ra sân vườn phía sau.', 12, 15, '[{"label":"Gara","kind":"garage","x":0,"y":0,"w":4,"h":6},{"label":"Phòng khách","kind":"living","x":4,"y":0,"w":8,"h":7},{"label":"Phòng ngủ khách","kind":"bed","x":0,"y":6,"w":4,"h":5},{"label":"Bếp & ăn","kind":"kitchen","x":4,"y":7,"w":8,"h":5},{"label":"WC","kind":"wc","x":0,"y":11,"w":4,"h":2},{"label":"Kho","kind":"storage","x":0,"y":13,"w":4,"h":2},{"label":"Sân vườn","kind":"outdoor","x":4,"y":12,"w":8,"h":3}]'::jsonb, 0),
  ('t2', 'Tầng 2', 'T2', 180, 3, 2, 'Phòng ngủ master kèm phòng thay đồ và WC riêng, sảnh sinh hoạt chung cho gia đình.', 12, 15, '[{"label":"Phòng ngủ master","kind":"bed","x":0,"y":0,"w":7,"h":6},{"label":"WC master","kind":"wc","x":7,"y":0,"w":5,"h":3},{"label":"Phòng thay đồ","kind":"storage","x":7,"y":3,"w":5,"h":3},{"label":"Sảnh sinh hoạt","kind":"living","x":0,"y":6,"w":5,"h":5},{"label":"Phòng ngủ 2","kind":"bed","x":5,"y":6,"w":7,"h":5},{"label":"Phòng ngủ 3","kind":"bed","x":0,"y":11,"w":6,"h":4},{"label":"WC","kind":"wc","x":6,"y":11,"w":3,"h":4},{"label":"Ban công","kind":"outdoor","x":9,"y":11,"w":3,"h":4}]'::jsonb, 1)
) as v (slug, name, code, area, bedrooms, bathrooms, note, width, depth, rooms, sort_order);

values ('land', 'Mặt bằng nhà phố gợi ý', 'Lô đất tiêu chuẩn 5 × 20m. Dưới đây là phương án thiết kế nhà phố 2 tầng gợi ý từ đội ngũ kiến trúc sư của Terra, giúp khách hàng hình dung công năng khi xây dựng.')
on conflict (building_type) where project_id is null do update set title = excluded.title, intro = excluded.intro;
delete from public.floor_plans where set_id = (select id from public.floor_plan_sets where building_type = 'land' and project_id is null);
select (select id from public.floor_plan_sets where building_type = 'land' and project_id is null), v.slug, v.name, v.code, v.area::numeric, v.bedrooms::int, v.bathrooms::int, v.note,
  v.width::numeric, v.depth::numeric, v.rooms::jsonb, v.sort_order::int
from (values
  ('l1', 'Tầng trệt', 'L1', 100, null, 1, 'Sân trước để xe, phòng khách rộng, giếng trời lấy sáng giữa nhà.', 5, 20, '[{"label":"Sân trước","kind":"outdoor","x":0,"y":0,"w":5,"h":3},{"label":"Phòng khách","kind":"living","x":0,"y":3,"w":5,"h":6},{"label":"Thang","kind":"stair","x":0,"y":9,"w":2,"h":3},{"label":"WC","kind":"wc","x":2,"y":9,"w":3,"h":2},{"label":"Giếng trời","kind":"outdoor","x":2,"y":11,"w":3,"h":1},{"label":"Bếp & ăn","kind":"kitchen","x":0,"y":12,"w":5,"h":6},{"label":"Sân sau","kind":"outdoor","x":0,"y":18,"w":5,"h":2}]'::jsonb, 0),
  ('l2', 'Tầng 1', 'L2', 100, 2, 1, 'Hai phòng ngủ trước – sau đều có cửa sổ lớn, sân phơi riêng phía sau.', 5, 20, '[{"label":"Ban công","kind":"outdoor","x":0,"y":0,"w":5,"h":2},{"label":"Phòng ngủ 1","kind":"bed","x":0,"y":2,"w":5,"h":6},{"label":"Thang","kind":"stair","x":0,"y":8,"w":2,"h":3},{"label":"WC","kind":"wc","x":2,"y":8,"w":3,"h":3},{"label":"Phòng ngủ 2","kind":"bed","x":0,"y":11,"w":5,"h":6},{"label":"Sân phơi","kind":"outdoor","x":0,"y":17,"w":5,"h":3}]'::jsonb, 1)
) as v (slug, name, code, area, bedrooms, bathrooms, note, width, depth, rooms, sort_order);

values ('shophouse', 'Mặt bằng shophouse', 'Shophouse 6 × 18m: tầng trệt mặt tiền rộng tối ưu cho kinh doanh, các tầng trên bố trí khép kín để gia đình ở hoặc cho thuê văn phòng.')
on conflict (building_type) where project_id is null do update set title = excluded.title, intro = excluded.intro;
delete from public.floor_plans where set_id = (select id from public.floor_plan_sets where building_type = 'shophouse' and project_id is null);
select (select id from public.floor_plan_sets where building_type = 'shophouse' and project_id is null), v.slug, v.name, v.code, v.area::numeric, v.bedrooms::int, v.bathrooms::int, v.note,
  v.width::numeric, v.depth::numeric, v.rooms::jsonb, v.sort_order::int
from (values
  ('s1', 'Tầng trệt kinh doanh', 'S1', 108, null, 1, 'Không gian kinh doanh thông thoáng 60m², kho và bếp riêng phía sau.', 6, 18, '[{"label":"Khu kinh doanh","kind":"shop","x":0,"y":0,"w":6,"h":10},{"label":"Kho","kind":"storage","x":0,"y":10,"w":3,"h":2},{"label":"WC","kind":"wc","x":0,"y":12,"w":3,"h":2},{"label":"Thang","kind":"stair","x":3,"y":10,"w":3,"h":4},{"label":"Bếp","kind":"kitchen","x":0,"y":14,"w":6,"h":4}]'::jsonb, 0),
  ('s2', 'Tầng 2 – 3 ở', 'S2', 108, 2, 1, 'Phòng khách hướng ra mặt phố, hai phòng ngủ yên tĩnh phía sau.', 6, 18, '[{"label":"Phòng khách","kind":"living","x":0,"y":0,"w":6,"h":6},{"label":"Phòng ngủ 1","kind":"bed","x":0,"y":6,"w":6,"h":5},{"label":"WC","kind":"wc","x":0,"y":11,"w":3,"h":4},{"label":"Thang","kind":"stair","x":3,"y":11,"w":3,"h":4},{"label":"Phòng ngủ 2","kind":"bed","x":0,"y":15,"w":6,"h":3}]'::jsonb, 1)
) as v (slug, name, code, area, bedrooms, bathrooms, note, width, depth, rooms, sort_order);

commit;
